def find_components(rows, cols, grid):
    visited = set()
    components = {}

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                comp = set()
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    comp.add((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and (nr, nc) not in visited:
                            stack.append((nr, nc))

                rs = [p[0] for p in comp]
                cs = [p[1] for p in comp]
                min_r, max_r = min(rs), max(rs)
                min_c, max_c = min(cs), max(cs)
                height = max_r - min_r + 1
                width = max_c - min_c + 1

                components[color] = {
                    'positions': comp,
                    'height': height,
                    'width': width,
                    'count': len(comp),
                    'min_r': min_r,
                    'max_r': max_r,
                    'min_c': min_c,
                    'max_c': max_c,
                    'bbox': (min_r, min_c, max_r, max_c)
                }
    return components

